style.css:
@-moz-document domain("google.com") {
html {
    /* Wallpaper image (replace URL) */
    background: url('https://example.com/your-image.jpg') center/cover fixed !important;
    
    /* Optional fallback solid color */
    background-color: #2a4a6e !important;
  }
  
  /* Semi-transparent overlay to improve text readability */
  body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.3); /* Dark overlay (adjust opacity) */
    z-index: -1;
  }


  /* Make page content semi-transparent */
  body {
    background: transparent !important;
    color: #f0f0f0 !important; /* Light text color */
  }


  /* Fix for elements with hardcoded backgrounds */
  div, section, article, main, header, footer {
    background: transparent !important;
  }
}
